using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using TeatroSESI;using Maracannes;
namespace TeatroSESI.Urban {
public sealed class UrbanRuntimeAudit:MonoBehaviour {
 static void SaveShot(string path){var texture=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(path,texture.EncodeToPNG());Destroy(texture);}
 const string B="Assets/Teatro_Centro_SESI/Entorno_Urbano/References/";
 static bool IsBuildTest=>Environment.GetCommandLineArgs().Contains("-urban-verify");
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(!IsBuildTest)return;Application.runInBackground=true;if(SceneManager.GetActiveScene().path!=AcervoTravel.Theater)SceneManager.LoadScene(AcervoTravel.Theater);}
 IEnumerator Start(){bool build=IsBuildTest;if(!build&&(!File.Exists(B+"urban-test.request")||File.ReadAllText(B+"urban-test.request").Trim()!="run"))yield break;if(!build)File.WriteAllText(B+"urban-test.request","running");yield return new WaitForSecondsRealtime(1);var args=Environment.GetCommandLineArgs();int outputIndex=Array.IndexOf(args,"-urban-output");string output=build&&outputIndex>=0?args[outputIndex+1]:"Builds/Urban_PlayMode_Verification";Directory.CreateDirectory(output);var log=new List<string>();bool ok=true;var visitor=FindAnyObjectByType<VisitaCentroSESI>();var camera=visitor.cameraVisita;var env=GetComponent<UrbanDaylight>();bool sky=RenderSettings.skybox==env.skybox&&env.skybox.shader.isSupported&&camera.clearFlags==CameraClearFlags.Skybox;ok&=sky;log.Add((sky?"PASS":"FAIL")+" Skybox HDRI válido, shader suportado e câmera principal em Skybox");var buildings=GetComponentsInChildren<UrbanBuilding>();bool geometry=buildings.Length==11&&buildings.All(b=>b.GetComponent<LODGroup>()&&b.GetComponentsInChildren<MeshCollider>().Length>0);ok&=geometry;log.Add((geometry?"PASS":"FAIL")+" 11 edifícios tridimensionais com colisões e LOD");bool materials=GetComponentsInChildren<Renderer>().All(r=>r.sharedMaterials.All(m=>m&&m.shader&&m.shader.isSupported));ok&=materials;log.Add((materials?"PASS":"FAIL")+" Materiais locais válidos, sem shader ausente");visitor.autoWalking=true;visitor.autoTarget=new Vector3(0,0,-31);float end=Time.realtimeSinceStartup+8;while(Vector2.Distance(new Vector2(visitor.transform.position.x,visitor.transform.position.z),new Vector2(0,-31))>.25f&&Time.realtimeSinceStartup<end)yield return null;visitor.autoWalking=false;bool walking=visitor.transform.position.y>-.35f&&Mathf.Abs(visitor.transform.position.x)<.4f&&Mathf.Abs(visitor.transform.position.z+31)<.3f;ok&=walking;log.Add((walking?"PASS":"FAIL")+" Caminhada exterior até entrada com piso e colisões");visitor.enabled=false;
 Vector3[] positions={new Vector3(0,.05f,-50),new Vector3(-48,.05f,-42),new Vector3(18,.05f,-50)};Vector3[] targets={new Vector3(4,12,-20),new Vector3(9,15,-25),new Vector3(75,80,-45)};
 for(int i=0;i<3;i++){visitor.GetComponent<AcervoTravel>().SetPosition(positions[i],0);camera.transform.LookAt(targets[i]);yield return new WaitForEndOfFrame();SaveShot(Path.Combine(output,"Entorno_"+i+".png"));yield return null;}
 camera.transform.rotation=Quaternion.Euler(-45,180,0);yield return new WaitForEndOfFrame();SaveShot(Path.Combine(output,"Ceu_Runtime.png"));yield return null;log.Add("Renderers: "+GetComponentsInChildren<Renderer>().Length+"; triângulos LOD0+LOD1: "+GetComponentsInChildren<MeshFilter>().Sum(m=>m.sharedMesh?(long)m.sharedMesh.GetIndexCount(0)/3:0));File.WriteAllLines(Path.Combine(output,build?"urban-build-runtime.txt":"urban-runtime.txt"),new[]{(ok?"PASS":"FAIL")+" · "+(build?"Build Windows":"Play Mode")+" · céu, edifícios e circulação"}.Concat(log));if(build){Application.Quit(ok?0:1);yield break;}File.Copy(Path.Combine(output,"urban-runtime.txt"),B+"urban-runtime.txt",true);File.WriteAllText(B+"urban-test.request","done");
 #if UNITY_EDITOR
 UnityEditor.EditorApplication.delayCall+=()=>UnityEditor.EditorApplication.isPlaying=false;
 #endif
 }
}
}


